task text_match(s: seq) returns (r: seq)
  ensures len(r) == 1
  ensures r == ['Found a match!'] or r == ['Not matched!']
{
  if len(s) >= 1 and s[0] == 'a' {
    var i: int := 1;
    while i < len(s) and s[i] == 'b'
      invariant 1 <= i and i <= len(s)
      invariant forall j in [0, i) . s[j] == 'a' or j == 0 and i == 1
      decreases len(s) - i
    {
      i := i + 1;
    }
    r := ['Found a match!'];
  } else {
    r := ['Not matched!'];
  }
}
